#[summary("clamp a value into a range")]
mod tasks {
    #[effects(pure)]
    #[uses(is_clamp)]
    fn clamp(x: i64, lo: i64, hi: i64) -> (r: i64)
        requires le(lo, hi),
        ensures is_clamp(x, lo, hi, r),
    {
        if x < lo {
            lo
        } else if x > hi {
            hi
        } else {
            x
        }
    }

    spec fn is_clamp(x: i64, lo: i64, hi: i64, r: i64) -> bool {
        if x < lo {
            r == lo
        } else if x > hi {
            r == hi
        } else {
            r == x
        }
    }

    spec fn le(lo: i64, hi: i64) -> bool {
        lo <= hi
    }
}

#[summary("floor midpoint of two i64 values")]
mod tasks {
    spec fn is_mid(a: i64, b: i64, r: i64) -> bool {
        2 * r <= a + b && a + b < 2 * r + 2
    }

    #[effects(pure)]
    #[uses(is_mid)]
    fn midpoint(a: i64, b: i64) -> (r: i64)
        ensures is_mid(a, b, r),
    {
        let la: i64 = (a % 2 + 2) % 2;
        let lb: i64 = (b % 2 + 2) % 2;
        let fa: i64 = (a - la) / 2;
        let fb: i64 = (b - lb) / 2;
        fa + fb + (la + lb) / 2
    }
}

#[summary("saturating sum")]
mod tasks {
    #[uses(sat_prefix)]
    spec fn done(a: &[i64], r: i64) -> bool {
        r == sat_prefix(a, a.len())
    }

    #[uses(sat_prefix)]
    spec fn inv(a: &[i64], i: usize, s: i64) -> bool {
        i <= a.len() && s == sat_prefix(a, i)
    }

    #[uses(sat_step)]
    spec fn sat_prefix(a: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else {
            sat_step(sat_prefix(a, n - 1), a[n - 1])
        }
    }

    spec fn sat_step(s: i64, y: i64) -> i64 {
        if s + y > i64::MAX {
            i64::MAX
        } else {
            if s + y < i64::MIN {
                i64::MIN
            } else {
                s + y
            }
        }
    }

    #[effects(pure)]
    #[uses(done, inv, sat_prefix, sat_step)]
    fn sat_sum(a: &[i64]) -> (r: i64)
        ensures done(a, r),
    {
        let mut s: i64 = 0;
        let mut i: usize = 0;
        while i < a.len()
            invariant inv(a, i, s),
            decreases a.len() - i,
        {
            let y: i64 = a[i];
            s = if y > 0 {
                if s > i64::MAX - y {
                    i64::MAX
                } else {
                    s + y
                }
            } else {
                if s < i64::MIN - y {
                    i64::MIN
                } else {
                    s + y
                }
            };
            i = i + 1;
        }
        s
    }
}

#[summary("count elements in inclusive range")]
mod tasks {
    spec fn cnt(a: &[i64], n: usize, lo: i64, hi: i64) -> usize
        decreases n,
    {
        if n == 0 {
            0
        } else if lo <= a[n - 1] && a[n - 1] <= hi {
            cnt(a, n - 1, lo, hi) + 1
        } else {
            cnt(a, n - 1, lo, hi)
        }
    }

    #[effects(pure)]
    #[uses(cnt, inv, post)]
    fn count_in_range(a: &[i64], lo: i64, hi: i64) -> (r: usize)
        ensures post(a, lo, hi, r),
    {
        let mut i: usize = 0;
        let mut c: usize = 0;
        while i < a.len()
            invariant inv(a, i, c, lo, hi),
            decreases a.len() - i,
        {
            if lo <= a[i] && a[i] <= hi {
                c = c + 1;
            }
            i = i + 1;
        }
        c
    }

    #[uses(cnt)]
    spec fn inv(a: &[i64], i: usize, c: usize, lo: i64, hi: i64) -> bool {
        i <= a.len() && c <= i && c == cnt(a, i, lo, hi)
    }

    #[uses(cnt)]
    spec fn post(a: &[i64], lo: i64, hi: i64, r: usize) -> bool {
        r == cnt(a, a.len(), lo, hi)
    }
}

#[summary("first index of the maximum")]
mod tasks {
    #[effects(pure)]
    #[uses(inv, is_first_max, nonempty)]
    fn first_max_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures is_first_max(a, r),
    {
        let mut i: usize = 1;
        let mut best: usize = 0;
        while i < a.len()
            invariant inv(a, i, best),
            decreases a.len() - i,
        {
            if a[i] > a[best] {
                best = i;
            }
            i = i + 1;
        }
        best
    }

    spec fn inv(a: &[i64], i: usize, r: usize) -> bool {
        r < i && (i <= a.len() && ((forall|j: usize| j < i ==> #[trigger] a[j] <= a[r]) && (forall|k: usize| k < r ==> #[trigger] a[k] < a[r])))
    }

    spec fn is_first_max(a: &[i64], r: usize) -> bool {
        r < a.len() && ((forall|j: usize| j < a.len() ==> #[trigger] a[j] <= a[r]) && (forall|k: usize| k < r ==> #[trigger] a[k] < a[r]))
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("index of last minimum")]
mod tasks {
    #[effects(pure)]
    #[uses(min_upto, nonempty)]
    fn last_min_index(a: &[i64]) -> (r: usize)
        requires nonempty(a),
        ensures min_upto(a, r, a.len()),
    {
        let mut m: usize = 0;
        let mut i: usize = 1;
        while i < a.len()
            invariant min_upto(a, m, i),
            decreases a.len() - i,
        {
            if a[i] <= a[m] {
                m = i;
            }
            i = i + 1;
        }
        m
    }

    spec fn min_upto(a: &[i64], m: usize, i: usize) -> bool {
        m < i && i <= a.len() && (forall|j: usize| j < i ==> a[m] <= #[trigger] a[j] && (m < j ==> a[m] < a[j]))
    }

    spec fn nonempty(a: &[i64]) -> bool {
        a.len() > 0
    }
}

#[summary("strictly increasing check")]
mod tasks {
    spec fn inc_upto(a: &[i64], k: usize) -> bool {
        forall|i: usize| i < k && i + 1 < a.len() ==> #[trigger] a[i] < a[i + 1]
    }

    #[uses(inc_upto)]
    spec fn is_strict(a: &[i64], r: bool) -> bool {
        r == inc_upto(a, a.len())
    }

    #[effects(pure)]
    #[uses(inc_upto, is_strict)]
    fn strictly_increasing(a: &[i64]) -> (r: bool)
        ensures is_strict(a, r),
    {
        let mut i: usize = 0;
        let mut ok: bool = true;
        while ok && i + 1 < a.len()
            invariant i <= a.len(), ok ==> inc_upto(a, i), !ok ==> !inc_upto(a, a.len()),
            decreases a.len() - i,
        {
            if a[i] < a[i + 1] {
                i = i + 1;
            } else {
                ok = false;
                i = i + 1;
            }
        }
        ok
    }
}

#[summary("binary search lower bound")]
mod tasks {
    spec fn above(a: &[i64], t: i64, hi: usize) -> bool {
        forall|i: usize| hi <= i && i < a.len() ==> t <= #[trigger] a[i]
    }

    spec fn below(a: &[i64], t: i64, lo: usize) -> bool {
        forall|i: usize| i < lo && i < a.len() ==> #[trigger] a[i] < t
    }

    #[uses(above, below)]
    spec fn bounds(a: &[i64], t: i64, lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len() && (below(a, t, lo) && above(a, t, hi))
    }

    #[effects(pure)]
    #[uses(above, below, bounds, sorted)]
    fn lower_bound(a: &[i64], t: i64) -> (r: usize)
        requires sorted(a),
        ensures bounds(a, t, r, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = a.len();
        while lo < hi
            invariant bounds(a, t, lo, hi),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if a[mid] < t {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        lo
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }
}

#[summary("floor division")]
mod tasks {
    #[effects(pure)]
    #[uses(dom, isfloor)]
    fn div_floor(a: i64, b: i64) -> (r: i64)
        requires dom(a, b),
        ensures isfloor(a, b, r),
    {
        let q: i64 = a / b;
        let m: i64 = a % b;
        if m != 0 && (m < 0 && b > 0 || m > 0 && b < 0) {
            q - 1
        } else {
            q
        }
    }

    spec fn dom(a: i64, b: i64) -> bool {
        b != 0 && (a + 9223372036854775807 >= 0 || b + 1 != 0)
    }

    spec fn isfloor(a: i64, b: i64, r: i64) -> bool {
        (b <= 0 || r * b <= a && a < r * b + b) && (b >= 0 || r * b >= a && a > r * b + b)
    }
}

#[summary("floor-division remainder")]
mod tasks {
    #[effects(pure)]
    #[uses(mod_floor_post, mod_floor_pre)]
    fn mod_floor(a: i64, b: i64) -> (r: i64)
        requires mod_floor_pre(b),
        ensures mod_floor_post(a, b, r),
    {
        if b == -1 {
            0
        } else {
            let m: i64 = a % b;
            if m != 0 && (m < 0) != (b < 0) {
                m + b
            } else {
                m
            }
        }
    }

    spec fn mod_floor_post(a: i64, b: i64, r: i64) -> bool {
        (b <= 0 || 0 <= r && r < b) && (b >= 0 || b < r && r <= 0) && (a - r) % b == 0
    }

    spec fn mod_floor_pre(b: i64) -> bool {
        b != 0
    }
}

#[summary("max subarray")]
mod tasks {
    spec fn bnd(k: usize, c: i64, b: i64) -> bool {
        k <= 1000000 && 0 <= c + 1000000000 * k && c <= 1000000000 * k && (0 <= b + 1000000000 && b <= 1000000000 * k)
    }

    spec fn dom(a: &[i64]) -> bool {
        0 < a.len() && a.len() <= 1000000 && (forall|p: usize| p < a.len() ==> 0 <= #[trigger] a[p] + 1000000000 && a[p] <= 1000000000)
    }

    #[uses(sum)]
    spec fn max_all(a: &[i64], k: usize, b: i64) -> bool {
        (exists|i: usize, j: usize| i < j && j <= k && #[trigger] sum(a, i, j) == b) && (forall|p: usize, q: usize| p < q && q <= k ==> #[trigger] sum(a, p, q) <= b)
    }

    #[uses(sum)]
    spec fn max_end(a: &[i64], k: usize, c: i64) -> bool {
        (exists|i: usize| i < k && #[trigger] sum(a, i, k) == c) && (forall|p: usize| p < k ==> #[trigger] sum(a, p, k) <= c)
    }

    #[effects(pure)]
    #[uses(bnd, dom, max_all, max_end, sum)]
    fn max_subarray(a: &[i64]) -> (r: i64)
        requires dom(a),
        ensures max_all(a, a.len(), r),
    {
        let mut cur: i64 = a[0];
        let mut best: i64 = cur;
        let mut k: usize = 1;
        assert(sum(a, 0, 1) == cur);
        while k < a.len()
            invariant 1 <= k && k <= a.len(), max_end(a, k, cur), max_all(a, k, best), bnd(k, cur, best), dom(a),
            decreases a.len() - k,
        {
            let x: i64 = a[k];
            assert(forall|p: usize| p <= k ==> #[trigger] sum(a, p, k + 1) == sum(a, p, k) + x);
            if cur > 0 {
                cur = cur + x;
            } else {
                cur = x;
            }
            if cur > best {
                best = cur;
            }
            k = k + 1;
        }
        best
    }

    spec fn sum(a: &[i64], i: usize, j: usize) -> i64
        decreases j,
    {
        if j <= i {
            0
        } else {
            sum(a, i, j - 1) + a[j - 1]
        }
    }
}

#[summary("second largest distinct value")]
mod tasks {
    spec fn alleq(a: &[i64], n: usize, v: i64) -> bool {
        forall|k: usize| k < n && k < a.len() ==> #[trigger] a[k] == v
    }

    spec fn bnd(a: &[i64], n: usize, m: i64) -> bool {
        forall|k: usize| k < n && k < a.len() ==> #[trigger] a[k] <= m
    }

    spec fn has(a: &[i64], n: usize, v: i64) -> bool {
        exists|k: usize| k < n && k < a.len() && #[trigger] a[k] == v
    }

    #[uses(alleq, bnd, has, rest)]
    spec fn ok(a: &[i64], r: i64) -> bool {
        has(a, a.len(), r) && (exists|k: usize| k < a.len() && #[trigger] a[k] > r && (bnd(a, a.len(), a[k]) && rest(a, a.len(), r, a[k]))) || r == i64::MIN && (a.len() == 0 || alleq(a, a.len(), a[0]))
    }

    spec fn rest(a: &[i64], n: usize, s: i64, m: i64) -> bool {
        forall|k: usize| k < n && k < a.len() ==> #[trigger] a[k] <= s || a[k] == m
    }

    #[effects(pure)]
    #[uses(alleq, bnd, has, ok, rest)]
    fn second_max(a: &[i64]) -> (r: i64)
        ensures ok(a, r),
    {
        if a.len() == 0 {
            i64::MIN
        } else {
            let mut m: i64 = a[0];
            let mut i: usize = 1;
            while i < a.len()
                invariant i <= a.len(), i >= 1, bnd(a, i, m), has(a, i, m),
                decreases a.len() - i,
            {
                if a[i] > m {
                    m = a[i];
                }
                i = i + 1;
            }
            let mut s: i64 = i64::MIN;
            let mut found: bool = false;
            let mut j: usize = 0;
            while j < a.len()
                invariant j <= a.len(), bnd(a, a.len(), m), has(a, a.len(), m), rest(a, j, s, m), found && has(a, j, s) && s < m || found == false && s == i64::MIN && alleq(a, j, m),
                decreases a.len() - j,
            {
                if a[j] < m && (found == false || a[j] > s) {
                    s = a[j];
                    found = true;
                }
                j = j + 1;
            }
            s
        }
    }
}

#[summary("x")]
mod tasks {
    spec fn bnd(lo: usize, hi: usize, i: usize, j: usize) -> bool {
        lo <= i && i <= j && (j <= hi && i + j == lo + hi)
    }

    #[effects(pure)]
    #[uses(lt_len, rev_pre, rot_mid, rv)]
    fn core(a: &mut [i64], r: usize) -> ()
        requires lt_len(a, r),
        ensures rot_mid(a, old(a), r),
    {
        let n: usize = a.len();
        rev(a, 0, n);
        rev(a, 0, r);
        rev(a, r, n);
        ()
    }

    spec fn lt_len(a: &[i64], r: usize) -> bool {
        r < a.len()
    }

    #[effects(pure)]
    #[uses(bnd, rev_pre, rv)]
    fn rev(a: &mut [i64], lo: usize, hi: usize) -> ()
        requires rev_pre(a, lo, hi),
        ensures rv(a, old(a), lo, hi, lo, lo),
    {
        let mut i: usize = lo;
        let mut j: usize = hi;
        while i + 1 < j
            invariant bnd(lo, hi, i, j), rv(a, old(a), lo, hi, i, j),
            decreases j - i,
        {
            let t: i64 = a[i];
            a[i] = a[j - 1];
            a[j - 1] = t;
            i = i + 1;
            j = j - 1;
        }
        ()
    }

    spec fn rev_pre(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    spec fn rot_mid(a: &[i64], o: &[i64], r: usize) -> bool {
        a.len() == o.len() && (forall|j: usize| j < a.len() ==> (r <= j ==> #[trigger] a[j] == o[j - r]) && (j < r ==> a[j] == o[a.len() - r + j]))
    }

    #[uses(rot_mid)]
    spec fn rot_post(a: &[i64], o: &[i64], k: usize) -> bool {
        a.len() == o.len() && (a.len() > 0 ==> rot_mid(a, o, k % a.len()))
    }

    #[effects(pure)]
    #[uses(lt_len, rot_mid, rot_post)]
    fn rotate_right(a: &mut [i64], k: usize) -> ()
        ensures rot_post(a, old(a), k),
    {
        let n: usize = a.len();
        if n > 0 {
            let r: usize = k % n;
            core(a, r);
        }
        ()
    }

    spec fn rv(a: &[i64], o: &[i64], lo: usize, hi: usize, i: usize, j: usize) -> bool {
        a.len() == o.len() && (forall|k: usize| k < a.len() ==> (lo <= k && k < i || j <= k && k < hi ==> #[trigger] a[k] == o[lo + hi - 1 - k]) && (k < lo || i <= k && k < j || hi <= k ==> a[k] == o[k]))
    }
}

#[summary("dedup sorted")]
mod tasks {
    spec fn bnd(a: &[i64], w: usize, i: usize) -> bool {
        w <= i && i <= a.len()
    }

    #[uses(has)]
    spec fn cover(a: &[i64], w: usize, b: &[i64], n: usize) -> bool {
        forall|j: usize| j < n && j < b.len() ==> has(a, w, #[trigger] b[j])
    }

    #[effects(pure)]
    #[uses(bnd, cover, has, last_ok, le_at, le_len, lt_at, same_from, sorted, strict, zeros)]
    fn dedup_sorted(a: &mut [i64]) -> (r: usize)
        requires sorted(a),
        ensures le_len(a, r), strict(a, r), zeros(a, r, a.len()), cover(a, r, old(a), a.len()), cover(old(a), a.len(), a, r),
    {
        let n: usize = a.len();
        let mut w: usize = 0;
        let mut i: usize = 0;
        while i < n
            invariant n == a.len(), bnd(a, w, i), strict(a, w), cover(a, w, old(a), i), cover(old(a), i, a, w), same_from(a, old(a), i), last_ok(a, old(a), w, i), sorted(old(a)), old(a).len() == n,
            decreases n - i,
        {
            assert(0 < i ==> le_at(old(a), i - 1, i));
            if w == 0 || a[w - 1] < a[i] {
                a[w] = a[i];
                w = w + 1;
                assert(has(a, w, old(a)[i]));
            }
            assert(0 < w && a[w - 1] == old(a)[i]);
            assert(has(old(a), i + 1, a[w - 1]));
            assert(cover(old(a), i + 1, a, w));
            i = i + 1;
        }
        let mut j: usize = w;
        while j < n
            invariant n == a.len(), bnd(a, w, j), strict(a, w), cover(a, w, old(a), n), cover(old(a), n, a, w), zeros(a, w, j),
            decreases n - j,
        {
            a[j] = 0;
            j = j + 1;
        }
        w
    }

    #[effects(pure)]
    #[uses(cover, has)]
    fn grow(o: &[i64], a: &[i64], i: usize, w: usize) -> ()
        requires cover(o, i, a, w),
        ensures cover(o, i + 1, a, w),
    {}

    spec fn has(a: &[i64], n: usize, v: i64) -> bool {
        exists|k: usize| k < n && k < a.len() && #[trigger] a[k] == v
    }

    spec fn last_ok(a: &[i64], b: &[i64], w: usize, i: usize) -> bool {
        0 < i ==> 0 < w && w <= a.len() && i <= b.len() && a[w - 1] == b[i - 1]
    }

    spec fn le_at(a: &[i64], i: usize, j: usize) -> bool {
        i < a.len() && j < a.len() && a[i] <= a[j]
    }

    spec fn le_len(a: &[i64], r: usize) -> bool {
        r <= a.len()
    }

    spec fn lt_at(a: &[i64], i: usize, j: usize) -> bool {
        i < a.len() && j < a.len() && a[i] < a[j]
    }

    spec fn same_from(a: &[i64], b: &[i64], i: usize) -> bool {
        a.len() == b.len() && (forall|k: usize| i <= k && k < a.len() ==> #[trigger] a[k] == b[k])
    }

    #[uses(le_at)]
    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i < j && j < a.len() ==> #[trigger] le_at(a, i, j)
    }

    #[uses(lt_at)]
    spec fn strict(a: &[i64], r: usize) -> bool {
        forall|i: usize, j: usize| i < j && j < r ==> #[trigger] lt_at(a, i, j)
    }

    spec fn zeros(a: &[i64], w: usize, h: usize) -> bool {
        forall|k: usize| w <= k && (k < h && k < a.len()) ==> #[trigger] a[k] == 0
    }
}

#[summary("move zeros to the end of a slice")]
mod tasks {
    spec fn bounds(a: &[i64], j: usize, i: usize) -> bool {
        j <= i && i <= a.len()
    }

    #[effects(pure)]
    #[uses(bounds, nz_below, zero_between, zero_from, zeros_last)]
    fn move_zeros(a: &mut [i64]) -> ()
        ensures zeros_last(a),
    {
        let mut i: usize = 0;
        let mut j: usize = 0;
        while i < a.len()
            invariant bounds(a, j, i), nz_below(a, j), zero_between(a, j, i),
            decreases a.len() - i,
        {
            if a[i] != 0 {
                let t: i64 = a[i];
                a[i] = a[j];
                a[j] = t;
                j = j + 1;
            }
            i = i + 1;
        }
    }

    spec fn nz_below(a: &[i64], k: usize) -> bool {
        forall|p: usize| p < k ==> #[trigger] a[p] != 0
    }

    spec fn zero_between(a: &[i64], j: usize, i: usize) -> bool {
        forall|p: usize| j <= p && p < i ==> #[trigger] a[p] == 0
